+++ b/src/io/sales-import.js
@@ -0,0 +1,25 @@
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+/** Parses and imports a complete till CSV atomically. */
+export function importSalesCsv(store, text) {
+  const lines = text.split(/\r?\n/);
+  const rows = [];
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    if (!/^(?:[^",]*|"(?:[^"]|"")*")(?:,(?:[^",]*|"(?:[^"]|"")*"))*$/.test(line))
+      throw new AppError("bad_request", { reason: `row ${index + 1}: invalid CSV` });
+    rows.push({ fields: parseCsv(line)[0].map((v) => v.trim()), row: index + 1 });
+  }
+  const header = rows.shift()?.fields;
+  const columns = ["ticket", "soldAt", "dishId", "qty"];
+  if (!header || header.length !== columns.length || columns.some((c) => !header.includes(c)))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+  const entries = rows.map(({ fields, row }) => {
+    if (fields.length !== header.length)
+      throw new AppError("bad_request", { reason: `row ${row}: wrong number of fields` });
+    return { ...Object.fromEntries(header.map((key, i) => [key, fields[i]])), row };
+  });
+  return importSales(store, entries);
+}
